<script setup lang="ts">
import{computed,onMounted,onUnmounted,ref}from'vue'
import{useRoute}from'vue-router'
import{CalendarClock,CalendarPlus,CheckCircle2,Clock3,FilePlus2,Pencil,Play,RefreshCw,RotateCcw,ScrollText,Search,ShieldCheck,Square,Terminal,Trash2,Workflow,X,Zap}from'lucide-vue-next'
import{useAuthStore}from'@/stores/useAuthStore'
import{progressTone,statusLabel}from'@/features/jobs/jobsModel'
import type{Asset}from'@/features/cmdb/types'
import{createExecution,createPlaybook,createPlaybookExecution,createSchedule,createTemplate,deletePlaybook,deleteSchedule,deleteTemplate,duplicateTemplate,fetchJobAssets,fetchJobArtifact,fetchJobData,fetchJobTargetOptions,fetchRunnerOverview,jobAction,previewSchedule,resolveJobTargets,retryJob,reviewJob,runSchedule,togglePlaybook,toggleSchedule,toggleTemplate,updatePlaybook,updateSchedule,updateTemplate,type Job,type JobTargetOptions,type Playbook,type PlaybookInput,type Schedule,type ScheduleInput,type Summary,type Template,type ExecutorInfo,type RunnerOverview,type JobFilters}from'@/api/jobs'
import{listCredentials,type Credential}from'@/api/cmdb'

const auth=useAuthStore(),templates=ref<Template[]>([]),jobs=ref<Job[]>([]),schedules=ref<Schedule[]>([]),assets=ref<Asset[]>([]),summary=ref<Summary>(),executor=ref<ExecutorInfo>(),credentials=ref<Credential[]>([]),runnerOverview=ref<RunnerOverview>(),credentialId=ref(''),selected=ref<Job>(),tab=ref<'executions'|'schedules'|'approvals'|'runner'>('executions'),loading=ref(false),error=ref(''),jobFilters=ref<JobFilters>({q:'',status:'',projectGroup:'',tag:'',from:'',to:''})
const route=useRoute()
const workspace=ref<'overview'|'templates'|'playbooks'|'executions'|'schedules'|'approvals'|'runner'>('overview')
const editingTemplate=ref<Template>()
const targetOptions=ref<JobTargetOptions>({projectGroups:[],tags:[]})
const targetMode=ref<'asset'|'projectGroup'|'tag'|'ip'>('asset')
const selectedGroups=ref<string[]>([])
const selectedTags=ref<string[]>([])
const ipText=ref('')
const resolvedPreview=ref<{targets:string[];assets:Asset[]}>({targets:[],assets:[]})
const showTemplate=ref(false),showExecute=ref(false),activeTemplate=ref<Template>(),selectedTargets=ref<string[]>([]),timeoutSeconds=ref(300)
const templateForm=ref({name:'',category:'巡检',description:'',command:'',playbookId:'',parameters:{} as Record<string,string>,risk:'low' as 'low'|'medium'|'high'})
const showSchedule=ref(false),editingSchedule=ref<Schedule>(),scheduleSaving=ref(false),scheduleForm=ref<ScheduleInput>({name:'',templateId:'',playbookId:'',variables:{},parameters:{},targets:[],cron:'0 2 * * *',timezone:'Asia/Shanghai',concurrencyPolicy:'forbid',missedPolicy:'skip',timeoutSeconds:300,enabled:true,credentialId:''}),scheduleVariablesText=ref(''),scheduleParametersText=ref(''),scheduleNextRuns=ref<string[]>([]),schedulePreviewing=ref(false),schedulePreviewError=ref(''),approvalComment=ref('')
const cronPresets=[{label:'每小时',value:'0 * * * *'},{label:'每天 02:00',value:'0 2 * * *'},{label:'每周日 03:00',value:'0 3 * * 0'},{label:'每月 1 日 04:00',value:'0 4 1 * *'}]
const playbooks=ref<Playbook[]>([]),showPlaybook=ref(false),editingPlaybook=ref<Playbook>(),playbookSaving=ref(false),activePlaybook=ref<Playbook>(),executionVariables=ref<Record<string,string>>({})
const playbookForm=ref<PlaybookInput & {id:string}>({id:'',name:'',description:'',content:'',constants:{},variables:{},enabled:true})
const constantsText=ref(''),variablesText=ref('')
const onlineAssets=computed(()=>assets.value.filter(item=>item.status!=='offline'))
const sshCredentials=computed(()=>credentials.value.filter(item=>item.kind==='ssh'))
function credentialName(id:string){return credentials.value.find(item=>item.id===id)?.name||id||'服务端默认'}
function clearJobFilters(){jobFilters.value={q:'',status:'',projectGroup:'',tag:'',from:'',to:''};void load()}
async function load(){loading.value=true;error.value='';try{const selectedId=selected.value?.id||(typeof route.query.job==='string'?route.query.job:'');[summary.value,templates.value,jobs.value,schedules.value,playbooks.value,executor.value]=await fetchJobData(auth.token,jobFilters.value);credentials.value=await listCredentials(auth.token);try{runnerOverview.value=await fetchRunnerOverview(auth.token)}catch{}if(selectedId)selected.value=jobs.value.find(item=>item.id===selectedId)}catch(e){error.value=e instanceof Error?e.message:'加载失败'}finally{loading.value=false}}
async function openExecution(template:Template){activeTemplate.value=template;selectedTargets.value=[];credentialId.value='';targetMode.value='asset';selectedGroups.value=[];selectedTags.value=[];ipText.value='';resolvedPreview.value={targets:[],assets:[]};showExecute.value=true;void openTargetOptions();if(!assets.value.length){try{assets.value=(await fetchJobAssets(auth.token)).data}catch(e){error.value=e instanceof Error?e.message:'资产加载失败'}}}
async function submitExecution(){if((!activeTemplate.value&&!activePlaybook.value)||!selectedTargets.value.length)return;try{let job;if(activePlaybook.value)job=await createPlaybookExecution(auth.token,{playbookId:activePlaybook.value.id,targets:selectedTargets.value,variables:executionVariables.value,timeoutSeconds:timeoutSeconds.value,credentialId:credentialId.value});else job=await createExecution(auth.token,{templateId:activeTemplate.value!.id,targets:selectedTargets.value,timeoutSeconds:timeoutSeconds.value,credentialId:credentialId.value});if(job.status==='pending')job=await jobAction(auth.token,job.id,'run');showExecute.value=false;await load();selected.value=jobs.value.find(item=>item.id===job.id)}catch(e){error.value=e instanceof Error?e.message:'创建任务失败'}}
async function submitTemplate(){try{if(editingTemplate.value)await updateTemplate(auth.token,editingTemplate.value.id,templateForm.value);else await createTemplate(auth.token,templateForm.value);showTemplate.value=false;editingTemplate.value=undefined;templateForm.value={name:'',category:'巡检',description:'',command:'',playbookId:'',parameters:{},risk:'low'};await load()}catch(e){error.value=e instanceof Error?e.message:'模板保存失败'}}
function openTemplate(item?:Template){editingTemplate.value=item;templateForm.value=item?{name:item.name,category:item.category,description:item.description,command:item.command,playbookId:item.playbookId||'',parameters:{...(item.parameters||{})},risk:item.risk}:{name:'',category:'巡检',description:'',command:'',playbookId:'',parameters:{},risk:'low'};showTemplate.value=true;void openTargetOptions()}
async function duplicateTemplateItem(item:Template){try{await duplicateTemplate(auth.token,item.id);await load()}catch(e){error.value=e instanceof Error?e.message:'模板复制失败'}}
async function removeTemplateItem(item:Template){if(!window.confirm(`确定删除作业模板“${item.name}”吗？`))return;try{await deleteTemplate(auth.token,item.id);await load()}catch(e){error.value=e instanceof Error?e.message:'模板删除失败'}}
async function openTargetOptions(){if(targetOptions.value.projectGroups.length||targetOptions.value.tags.length)return;try{targetOptions.value=await fetchJobTargetOptions(auth.token)}catch{}}
async function resolvePreview(){try{resolvedPreview.value=await resolveJobTargets(auth.token,{projectGroups:targetMode.value==='projectGroup'?selectedGroups.value:[],tags:targetMode.value==='tag'?selectedTags.value:[],assetIds:targetMode.value==='asset'?selectedTargets.value:[],ips:targetMode.value==='ip'?ipText.value.split(/[,\s]+/).filter(Boolean):[]});selectedTargets.value=resolvedPreview.value.assets.map(item=>item.id)}catch(e){error.value=e instanceof Error?e.message:'目标解析失败'}}
async function toggle(item:Template){try{await toggleTemplate(auth.token,item.id);await load()}catch(e){error.value=e instanceof Error?e.message:'操作失败'}}
async function ensureAssets(){if(!assets.value.length){try{assets.value=(await fetchJobAssets(auth.token)).data}catch(e){error.value=e instanceof Error?e.message:'资产加载失败'}}}
async function openCreateSchedule(){await ensureAssets();editingSchedule.value=undefined;scheduleForm.value={name:'',templateId:templates.value.find(item=>item.enabled)?.id||'',playbookId:'',variables:{},parameters:{},targets:[],cron:'0 2 * * *',timezone:'Asia/Shanghai',concurrencyPolicy:'forbid',missedPolicy:'skip',timeoutSeconds:300,enabled:true,credentialId:''};scheduleVariablesText.value='';scheduleParametersText.value='';scheduleNextRuns.value=[];schedulePreviewError.value='';showSchedule.value=true;error.value='';void previewScheduleTimes()}
async function openEditSchedule(item:Schedule){await ensureAssets();editingSchedule.value=item;scheduleForm.value={name:item.name,templateId:item.templateId||'',playbookId:item.playbookId||'',variables:{...(item.variables||{})},parameters:{...(item.parameters||{})},targets:[...item.targets],cron:item.cron,timezone:item.timezone||'Asia/Shanghai',concurrencyPolicy:item.concurrencyPolicy||'forbid',missedPolicy:item.missedPolicy||'skip',timeoutSeconds:item.timeoutSeconds,enabled:item.enabled,credentialId:item.credentialId||''};scheduleVariablesText.value=mapToText(scheduleForm.value.variables);scheduleParametersText.value=mapToText(scheduleForm.value.parameters);scheduleNextRuns.value=[];schedulePreviewError.value='';showSchedule.value=true;error.value='';void previewScheduleTimes()}
async function submitSchedule(){scheduleForm.value.variables=parseKeyValues(scheduleVariablesText.value);scheduleForm.value.parameters=parseKeyValues(scheduleParametersText.value);if(!scheduleForm.value.name.trim()||(!scheduleForm.value.templateId&&!scheduleForm.value.playbookId)||!scheduleForm.value.cron.trim()||!scheduleForm.value.targets.length){error.value='请填写计划名称、作业模板或 Playbook、Cron 表达式并选择目标资产';return}scheduleSaving.value=true;try{if(editingSchedule.value)await updateSchedule(auth.token,editingSchedule.value.id,scheduleForm.value);else await createSchedule(auth.token,scheduleForm.value);showSchedule.value=false;await load()}catch(e){error.value=e instanceof Error?e.message:'计划保存失败'}finally{scheduleSaving.value=false}}
async function previewScheduleTimes(){if(!scheduleForm.value.cron.trim()){scheduleNextRuns.value=[];return}schedulePreviewing.value=true;schedulePreviewError.value='';try{scheduleNextRuns.value=(await previewSchedule(auth.token,{cron:scheduleForm.value.cron,timezone:scheduleForm.value.timezone,count:5})).nextRuns}catch(e){scheduleNextRuns.value=[];schedulePreviewError.value=e instanceof Error?e.message:'执行时间预览失败'}finally{schedulePreviewing.value=false}}
async function toggleScheduleItem(item:Schedule){try{await toggleSchedule(auth.token,item.id);await load()}catch(e){error.value=e instanceof Error?e.message:'计划状态更新失败'}}
async function runScheduleNow(item:Schedule){try{const job=await runSchedule(auth.token,item.id);await load();selected.value=jobs.value.find(value=>value.id===job.id);tab.value='executions'}catch(e){error.value=e instanceof Error?e.message:'立即执行失败'}}
async function removeScheduleItem(item:Schedule){if(!window.confirm(`确定删除计划“${item.name}”吗？`))return;try{await deleteSchedule(auth.token,item.id);await load()}catch(e){error.value=e instanceof Error?e.message:'计划删除失败'}}
function parseKeyValues(value:string){const out:Record<string,string>={};value.split(/\r?\n/).forEach(line=>{const index=line.indexOf('=');if(index<=0)return;const key=line.slice(0,index).trim();const text=line.slice(index+1).trim();if(key)out[key]=text});return out}
function mapToText(value?:Record<string,string>){return value?Object.entries(value).map(([key,text])=>`${key}=${text}`).join('\n'):''}
function openCreatePlaybook(){editingPlaybook.value=undefined;playbookForm.value={id:'',name:'',description:'',content:'',constants:{},variables:{},enabled:true};constantsText.value='';variablesText.value='';showPlaybook.value=true;error.value=''}
function editPlaybook(item:Playbook){editingPlaybook.value=item;playbookForm.value={id:item.id,name:item.name,description:item.description,content:item.content,constants:{...item.constants},variables:{...item.variables},enabled:item.enabled};constantsText.value=mapToText(item.constants);variablesText.value=mapToText(item.variables);showPlaybook.value=true;error.value=''}
async function submitPlaybook(){playbookForm.value.constants=parseKeyValues(constantsText.value);playbookForm.value.variables=parseKeyValues(variablesText.value);if(!playbookForm.value.name.trim()||!playbookForm.value.content.trim()){error.value='Playbook 名称和内容不能为空';return}playbookSaving.value=true;try{if(editingPlaybook.value)await updatePlaybook(auth.token,editingPlaybook.value.id,playbookForm.value);else await createPlaybook(auth.token,playbookForm.value);showPlaybook.value=false;await load()}catch(e){error.value=e instanceof Error?e.message:'Playbook 保存失败'}finally{playbookSaving.value=false}}
async function togglePlaybookItem(item:Playbook){try{await togglePlaybook(auth.token,item.id);await load()}catch(e){error.value=e instanceof Error?e.message:'Playbook 状态更新失败'}}
async function removePlaybookItem(item:Playbook){if(!window.confirm(`确定删除 Playbook“${item.name}”吗？`))return;try{await deletePlaybook(auth.token,item.id);await load()}catch(e){error.value=e instanceof Error?e.message:'Playbook 删除失败'}}
async function openPlaybookExecution(item:Playbook){await ensureAssets();activeTemplate.value=undefined;activePlaybook.value=item;executionVariables.value={...item.variables};selectedTargets.value=[];credentialId.value='';targetMode.value='asset';selectedGroups.value=[];selectedTags.value=[];ipText.value='';resolvedPreview.value={targets:[],assets:[]};showExecute.value=true;void openTargetOptions()}
async function action(job:Job,type:'run'|'retry'|'cancel'){try{await jobAction(auth.token,job.id,type);await load();selected.value=jobs.value.find(item=>item.id===job.id)}catch(e){error.value=e instanceof Error?e.message:'操作失败'}}
async function review(job:Job,decision:'approve'|'reject'|'return'){try{await reviewJob(auth.token,job.id,decision,approvalComment.value.trim());approvalComment.value='';await load();selected.value=jobs.value.find(item=>item.id===job.id)}catch(e){error.value=e instanceof Error?e.message:'审批操作失败'}}
async function retryFailed(job:Job){const targets=(job.targetResults||[]).filter(item=>item.status!=='success').map(item=>item.target);try{await retryJob(auth.token,job.id,targets);await load();selected.value=jobs.value.find(item=>item.id===job.id)}catch(e){error.value=e instanceof Error?e.message:'失败主机重试失败'}}
async function downloadArtifact(job:Job,index:number){try{const blob=await fetchJobArtifact(auth.token,job.id,index);const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=`${job.id}-artifact-${index+1}.zip`;document.body.appendChild(link);link.click();link.remove();URL.revokeObjectURL(url)}catch(e){error.value=e instanceof Error?e.message:'归档下载失败'}}
let timer:number,scheduleTimer:number;onMounted(()=>{load();timer=window.setInterval(()=>{if(jobs.value.some(item=>item.status==='running'))load()},1000);scheduleTimer=window.setInterval(()=>{if(schedules.value.some(item=>item.enabled))load()},30000)});onUnmounted(()=>{window.clearInterval(timer);window.clearInterval(scheduleTimer)})
</script>

<template><section class="jobs-page">
  <header class="jobs-heading"><div><span>AUTOMATION CONTROL PLANE</span><h1>自动化任务中心</h1><p>标准化作业、CMDB目标选择、安全审批与全程审计</p></div><div class="heading-actions"><span class="executor-state" :data-live="executor?.mode==='ansible-runner'&&executor.ready"><ShieldCheck/>{{executor?.mode==='ansible-runner'?(executor.ready?'Ansible Runner 已接入':'Ansible Runner 不可用'):'安全模拟执行'}}</span><button @click="showTemplate=true"><FilePlus2/>新建模板</button><button @click="load"><RefreshCw :class="{spin:loading}"/>刷新</button></div></header>
  <div v-if="error" class="jobs-error">{{error}}<button @click="error=''">关闭</button></div>
  <div class="jobs-summary"><article><Workflow/><span>作业模板<strong>{{summary?.templates}}</strong></span></article><article><Clock3/><span>执行中<strong>{{summary?.running}}</strong></span></article><article><CheckCircle2/><span>今日成功<strong>{{summary?.successToday}}</strong></span></article><article><RotateCcw/><span>今日失败<strong>{{summary?.failedToday}}</strong></span></article><article><CalendarClock/><span>调度计划<strong>{{summary?.schedules}}</strong></span></article></div>
  <section class="template-strip"><header><div><h2>作业模板</h2><span>作业模板封装 Playbook、默认参数、风险和审批策略</span></div><button @click="openTemplate()"><FilePlus2/>新建模板</button></header><div><article v-for="item in templates" :key="item.id" :class="{disabled:!item.enabled}"><b :data-risk="item.risk">{{item.category}} · {{item.risk}} · v{{item.version||1}}</b><h3>{{item.name}}</h3><p>{{item.description}}</p><code v-if="item.playbookId">Playbook：{{playbooks.find(p=>p.id===item.playbookId)?.name||item.playbookId}}</code><code v-else>{{item.command}}</code><footer><button class="subtle" @click="openTemplate(item)">编辑</button><button class="subtle" @click="duplicateTemplateItem(item)">复制</button><button class="subtle" @click="toggle(item)">{{item.enabled?'停用':'启用'}}</button><button :disabled="!item.enabled" @click="openExecution(item)"><Play/>执行</button><button class="subtle danger" @click="removeTemplateItem(item)">删除</button></footer></article></div></section>
  <section class="playbook-strip"><header><div><h2>Playbook 剧本</h2><span>定义常量、默认变量和命令内容，执行前由管理员审批</span></div><button @click="openCreatePlaybook"><FilePlus2/>新建 Playbook</button></header><div><article v-for="item in playbooks" :key="item.id" :class="{disabled:!item.enabled}"><b>Playbook · {{Object.keys(item.variables).length}} 个变量</b><h3>{{item.name}}</h3><p>{{item.description||'暂无描述'}}</p><code>{{item.content}}</code><footer><button class="subtle" @click="editPlaybook(item)">编辑</button><button class="subtle" @click="togglePlaybookItem(item)">{{item.enabled?'停用':'启用'}}</button><button :disabled="!item.enabled" @click="openPlaybookExecution(item)"><Play/>选择目标</button><button class="subtle" @click="removePlaybookItem(item)">删除</button></footer></article><div v-if="!playbooks.length" class="schedule-empty">暂无 Playbook，请先创建剧本</div></div></section>
  <div class="jobs-workspace"><main><nav><button :class="{active:tab==='executions'}" @click="tab='executions'">执行记录</button><button :class="{active:tab==='schedules'}" @click="tab='schedules'">调度计划</button><button :class="{active:tab==='approvals'}" @click="tab='approvals'">审批中心 {{jobs.filter(job=>job.status==='awaiting_approval').length?'('+jobs.filter(job=>job.status==='awaiting_approval').length+')':''}}</button><button :class="{active:tab==='runner'}" @click="tab='runner'">Runner 状态</button></nav><template v-if="tab==='executions'"><form class="job-filter-bar" @submit.prevent="load"><label>关键字<input v-model="jobFilters.q" placeholder="任务名、ID、执行人、目标"></label><label>状态<select v-model="jobFilters.status"><option value="">全部状态</option><option value="pending">待执行</option><option value="awaiting_approval">待审批</option><option value="running">执行中</option><option value="success">成功</option><option value="failed">失败</option><option value="cancelled">已取消</option><option value="rejected">已拒绝</option><option value="returned">已退回</option></select></label><label>项目组<input v-model="jobFilters.projectGroup" placeholder="例如 核心系统"></label><label>标签<input v-model="jobFilters.tag" placeholder="例如 k8s"></label><label>开始日期<input v-model="jobFilters.from" type="date"></label><label>结束日期<input v-model="jobFilters.to" type="date"></label><button><Search/>查询</button><button type="button" class="subtle" @click="clearJobFilters">清空</button></form><div class="job-filter-result"><span>筛选结果 {{jobs.length}} 条</span><small v-if="jobFilters.q||jobFilters.status||jobFilters.projectGroup||jobFilters.tag||jobFilters.from||jobFilters.to">已应用执行记录筛选条件</small></div><button v-for="job in jobs" :key="job.id" class="job-entry" :class="{selected:selected?.id===job.id}" @click="selected=job"><b :data-status="job.status">{{statusLabel(job.status)}}</b><div><strong>{{job.name}}</strong><span>{{job.targets.join('、')}} · {{job.operator}}</span></div><div class="entry-progress"><i :data-tone="progressTone(job.status)" :style="{width:job.progress+'%'}"></i></div><em>{{job.progress}}%</em><time>{{job.startedAt.slice(11)}}</time></button></template><template v-else-if="tab==='approvals'"><div class="schedule-toolbar"><div><strong>待审批任务</strong><span>审批人不能审批自己发起的高风险任务，可填写意见后通过、拒绝或退回修改</span></div></div><article v-for="job in jobs.filter(item=>item.status==='awaiting_approval')" :key="job.id" class="approval-card"><ShieldCheck/><div class="approval-impact"><strong>{{job.name}}</strong><span>申请人 {{job.operator}} · 影响 {{job.targets.length}} 台目标 · {{job.playbookId?'Playbook v'+(job.playbookVersion||1):'模板 v'+(job.templateVersion||1)}}</span><small>{{job.id}} · {{job.startedAt}} · 超时 {{job.timeoutSeconds}} 秒</small><div class="approval-targets"><span v-for="target in job.targets" :key="target">{{target}}</span></div><details><summary>查看变量、参数与执行内容</summary><pre>{{JSON.stringify({variables:job.variables,parameters:job.parameters},null,2)}}</pre></details></div><div class="approval-decision"><textarea v-model="approvalComment" rows="3" maxlength="1000" placeholder="审批意见（拒绝或退回时建议必填）"></textarea><div><button @click="review(job,'reject')"><X/>拒绝</button><button @click="review(job,'return')"><RotateCcw/>退回修改</button><button class="primary" @click="review(job,'approve')"><ShieldCheck/>审批通过</button></div></div></article><div v-if="!jobs.some(item=>item.status==='awaiting_approval')" class="schedule-empty">当前没有待审批任务</div></template><template v-else-if="tab==='schedules'"><div class="schedule-toolbar"><div><strong>调度计划</strong><span>按 Cron 自动创建并执行任务，模板和 Playbook 都支持</span></div><button @click="openCreateSchedule"><CalendarPlus/>新建计划</button></div><article v-for="schedule in schedules" :key="schedule.id" class="schedule-entry" :class="{disabled:!schedule.enabled}"><CalendarClock/><div><strong>{{schedule.name}}</strong><span>{{schedule.templateName||schedule.playbookName||schedule.templateId||schedule.playbookId}} · {{schedule.cron}} · {{schedule.targets.length}} 台目标 · 凭据 {{credentialName(schedule.credentialId)}}</span><small>{{schedule.timezone||'Asia/Shanghai'}} · 并发 {{schedule.concurrencyPolicy==='allow'?'允许':schedule.concurrencyPolicy==='replace'?'替换':'禁止'}} · 错过 {{schedule.missedPolicy==='run'?'补跑':'跳过'}}</small><small v-if="schedule.lastRun">上次 {{schedule.lastRun}} · {{schedule.lastStatus||'--'}}</small></div><time>{{schedule.enabled?`下次 ${schedule.nextRun||'待计算'}`:'已停用'}}</time><b :data-enabled="schedule.enabled">{{schedule.enabled?'已启用':'已停用'}}</b><div class="schedule-actions"><button @click="runScheduleNow(schedule)"><Zap/>立即执行</button><button @click="openEditSchedule(schedule)"><Pencil/>编辑</button><button @click="toggleScheduleItem(schedule)">{{schedule.enabled?'停用':'启用'}}</button><button @click="removeScheduleItem(schedule)"><Trash2/>删除</button></div></article><div v-if="!schedules.length" class="schedule-empty">暂无调度计划，请先创建作业模板或 Playbook</div></template><template v-else><div class="schedule-toolbar"><div><strong>Runner 运行状态</strong><span>查看执行器版本、能力、队列和当前运行任务</span></div><button @click="load"><RefreshCw :class="{spin:loading}"/>刷新状态</button></div><div v-if="runnerOverview" class="runner-overview"><section class="runner-capabilities"><header><div><small>EXECUTOR CAPABILITIES</small><h3>{{runnerOverview.capabilities.mode==='ansible-runner'?'Ansible Runner':'安全模拟执行器'}}</h3></div><b :data-ready="runnerOverview.capabilities.ready">{{runnerOverview.capabilities.ready?'在线':'不可用'}}</b></header><dl><div><dt>版本</dt><dd>{{runnerOverview.capabilities.version||'--'}}</dd></div><div><dt>最大目标数</dt><dd>{{runnerOverview.capabilities.maxTargets||'--'}}</dd></div><div><dt>归档能力</dt><dd>{{runnerOverview.capabilities.artifactArchive?'已启用':'未启用'}}</dd></div><div><dt>执行端点</dt><dd>{{runnerOverview.capabilities.endpoint||'本地模拟'}}</dd></div></dl><div class="runner-features"><span v-for="feature in runnerOverview.capabilities.features" :key="feature">{{feature}}</span></div><em v-if="runnerOverview.capabilities.error">{{runnerOverview.capabilities.error}}</em></section><section class="runner-queue"><h3>队列概览</h3><div><article><span>待执行</span><strong>{{runnerOverview.queue.pending}}</strong></article><article><span>待审批</span><strong>{{runnerOverview.queue.awaitingApproval}}</strong></article><article><span>运行中</span><strong>{{runnerOverview.queue.running}}</strong></article><article><span>失败</span><strong>{{runnerOverview.queue.failed}}</strong></article><article><span>成功</span><strong>{{runnerOverview.queue.success}}</strong></article></div></section><section class="runner-jobs"><header><h3>当前活动任务</h3><span>{{runnerOverview.activeJobs.length}} 个</span></header><article v-for="job in runnerOverview.activeJobs" :key="job.id" @click="selected=jobs.find(item=>item.id===job.id);tab='executions'"><b :data-status="job.status">{{statusLabel(job.status)}}</b><div><strong>{{job.name}}</strong><span>{{job.operator}} · {{job.targets.length}} 台目标 · 第 {{job.attempt}} 次</span></div><i :style="{width:job.progress+'%'}"></i><em>{{job.progress}}%</em></article><div v-if="!runnerOverview.activeJobs.length" class="schedule-empty">当前没有活动任务</div></section><section class="runner-profiles"><header><h3>已批准执行能力</h3><span>{{runnerOverview.capabilities.profiles.length}} 个 Profile</span></header><div><span v-for="profile in runnerOverview.capabilities.profiles" :key="profile">{{profile}}</span><em v-if="!runnerOverview.capabilities.profiles.length">无可用 Profile</em></div></section></div><div v-else class="schedule-empty">Runner 状态读取中或暂不可用</div></template></main>
    <aside class="job-console"><template v-if="selected"><header><div><span>EXECUTION DETAIL</span><h2>{{selected.name}}</h2></div><Terminal/></header><div class="console-meta"><span>{{selected.id}}</span><span>模板 v{{selected.templateVersion||1}}</span><span v-if="selected.playbookId">Playbook v{{selected.playbookVersion||1}}</span><span>凭据 {{credentialName(selected.credentialId)}}</span><span>第 {{selected.attempt}} 次</span><b :data-status="selected.status">{{statusLabel(selected.status)}}</b></div><div class="approval-note" v-if="selected.status==='awaiting_approval'">高风险任务等待审批，申请人 {{selected.operator}} 不能自审。</div><div v-if="selected.targetResults?.length" class="target-results"><h3>主机执行结果 <small>{{selected.targetResults.filter(x=>x.status==='success').length}}/{{selected.targetResults.length}} 成功</small></h3><article v-for="item in selected.targetResults" :key="item.target" :data-status="item.status"><header><strong>{{item.assetName||item.target}}</strong><b>{{item.status}}</b></header><small>返回码 {{item.rc}} · {{item.changed?'已变更':'无变更'}} · {{item.durationMs}}ms</small><pre v-if="item.stdout">{{item.stdout}}</pre><pre v-if="item.stderr" data-error="true">{{item.stderr}}</pre><em v-if="item.error">{{item.error}}</em></article></div><div v-if="selected.artifactKeys?.length" class="artifact-downloads"><h3>执行归档 <small>{{selected.artifactKeys.length}} 个</small></h3><button v-for="(artifact,index) in selected.artifactKeys" :key="artifact" @click="downloadArtifact(selected,index)"><ScrollText/>下载归档 {{index+1}}<span>{{artifact}}</span></button></div><h3 class="log-title">执行日志</h3><div class="log-stream"><p v-for="log in selected.logs" :key="log.time+log.message" :data-level="log.level"><time>{{log.time}}</time><b>[{{log.level}}]</b>{{log.message}}</p></div><footer><button v-if="selected.status==='awaiting_approval'" @click="review(selected,'approve')"><ShieldCheck/>审批通过</button><button v-if="selected.status==='pending'" @click="action(selected,'run')"><Play/>开始执行</button><button v-if="selected.status==='running'" @click="action(selected,'cancel')"><Square/>取消执行</button><button v-if="selected.targetResults?.some(item=>item.status!=='success')" @click="retryFailed(selected)"><RotateCcw/>仅重试失败主机</button><button v-if="selected.status==='failed'||selected.status==='cancelled'" @click="action(selected,'retry')"><RotateCcw/>全部重新执行</button></footer></template><div v-else class="empty-console"><ScrollText/><strong>选择执行记录</strong><span>查看主机结果、实时输出与审计日志</span></div></aside>
  </div>
  <div v-if="showTemplate" class="job-modal" @click.self="showTemplate=false"><form @submit.prevent="submitTemplate"><header><h2>{{editingTemplate?'编辑作业模板':'新建作业模板'}}</h2><button type="button" @click="showTemplate=false"><X/></button></header><label>模板名称<input v-model="templateForm.name" required maxlength="80"></label><label>分类<input v-model="templateForm.category" required maxlength="30"></label><label>描述<textarea v-model="templateForm.description" maxlength="300"></textarea></label><label>关联 Playbook<select v-model="templateForm.playbookId"><option value="">使用受控命令</option><option v-for="pb in playbooks.filter(x=>x.enabled)" :key="pb.id" :value="pb.id">{{pb.name}} · v{{pb.version||1}}</option></select></label><label v-if="!templateForm.playbookId">受控命令<input v-model="templateForm.command" maxlength="500" placeholder="例如 health-check --full"></label><label v-else>默认参数（每行 KEY=值）<textarea :value="Object.entries(templateForm.parameters).map(([k,v])=>k+'='+v).join('\n')" @input="templateForm.parameters=Object.fromEntries(($event.target as HTMLTextAreaElement).value.split('\n').map(x=>x.split('=')).filter(x=>x[0]).map(x=>[x[0].trim(),(x[1]||'').trim()]))" rows="4"></textarea></label><label>风险等级<select v-model="templateForm.risk"><option value="low">低风险</option><option value="medium">中风险</option><option value="high">高风险（需要审批）</option></select></label><footer><button type="button" @click="showTemplate=false">取消</button><button>{{editingTemplate?'保存修改':'保存模板'}}</button></footer></form></div>
  <div v-if="showExecute&&(activeTemplate||activePlaybook)" class="job-modal" @click.self="showExecute=false"><form class="target-dialog" @submit.prevent="submitExecution"><header><div><small>CREATE EXECUTION</small><h2>{{activeTemplate?.name||activePlaybook?.name}}</h2></div><button type="button" @click="showExecute=false"><X/></button></header><label>执行超时（秒）<input v-model.number="timeoutSeconds" type="number" min="10" max="86400"></label><label>SSH 凭据<select v-model="credentialId"><option value="">使用服务端默认密钥</option><option v-for="item in sshCredentials" :key="item.id" :value="item.id">{{item.name}} · {{item.username||'默认用户'}}</option></select></label><div class="target-mode-tabs"><button type="button" :class="{active:targetMode==='asset'}" @click="targetMode='asset'">资产选择</button><button type="button" :class="{active:targetMode==='projectGroup'}" @click="targetMode='projectGroup'">项目组</button><button type="button" :class="{active:targetMode==='tag'}" @click="targetMode='tag'">标签</button><button type="button" :class="{active:targetMode==='ip'}" @click="targetMode='ip'">IP / CIDR</button></div><div v-if="targetMode==='asset'"><h3>选择 CMDB 目标资产 <span>已选 {{selectedTargets.length}} 台</span></h3><div class="target-list"><label v-for="asset in onlineAssets" :key="asset.id"><input v-model="selectedTargets" type="checkbox" :value="asset.id"><div><strong>{{asset.name}}</strong><span>{{asset.ip||asset.id}} · {{asset.environment}} · {{asset.projectGroup}}</span></div><b>{{asset.status}}</b></label></div></div><div v-else-if="targetMode==='projectGroup'"><h3>项目组</h3><div class="selector-tags"><label v-for="group in targetOptions.projectGroups" :key="group"><input v-model="selectedGroups" type="checkbox" :value="group">{{group}}</label></div></div><div v-else-if="targetMode==='tag'"><h3>标签</h3><div class="selector-tags"><label v-for="tag in targetOptions.tags" :key="tag"><input v-model="selectedTags" type="checkbox" :value="tag">{{tag}}</label></div></div><div v-else><h3>IP / CIDR</h3><input v-model="ipText" placeholder="172.28.68.10, 172.28.69.0/24"></div><div class="target-preview"><button type="button" @click="resolvePreview">解析目标</button><span>匹配 {{resolvedPreview.assets.length}} 台，去重 {{resolvedPreview.targets.length}} 个 IP</span></div><footer><button type="button" @click="showExecute=false">取消</button><button :disabled="!selectedTargets.length"><Play/>创建并执行</button></footer></form></div>
  <div v-if="showSchedule" class="job-modal" @click.self="showSchedule=false"><form class="schedule-dialog" @submit.prevent="submitSchedule"><header><div><small>SCHEDULE CONTROL</small><h2>{{editingSchedule?'编辑调度计划':'新建调度计划'}}</h2></div><button type="button" @click="showSchedule=false"><X/></button></header><label>计划名称<input v-model="scheduleForm.name" required maxlength="80" placeholder="例如 每日凌晨主机巡检"></label><label>作业模板<select v-model="scheduleForm.templateId" @change="scheduleForm.playbookId=''"><option value="">不使用模板</option><option v-for="item in templates.filter(value=>value.enabled)" :key="item.id" :value="item.id">{{item.name}} · {{item.risk}}</option></select></label><label>或选择 Playbook<select v-model="scheduleForm.playbookId" @change="scheduleForm.templateId=''"><option value="">不使用 Playbook</option><option v-for="item in playbooks.filter(value=>value.enabled)" :key="item.id" :value="item.id">{{item.name}} · v{{item.version||1}}</option></select></label><label>执行周期（Cron）<input v-model="scheduleForm.cron" required placeholder="0 2 * * *"></label><div class="cron-presets"><button v-for="preset in cronPresets" :key="preset.value" type="button" :class="{active:scheduleForm.cron===preset.value}" @click="scheduleForm.cron=preset.value;previewScheduleTimes()">{{preset.label}}</button></div><div class="schedule-policy-grid"><label>时区<select v-model="scheduleForm.timezone" @change="previewScheduleTimes"><option value="Asia/Shanghai">Asia/Shanghai（中国标准时间）</option><option value="Asia/Hong_Kong">Asia/Hong_Kong</option><option value="Asia/Tokyo">Asia/Tokyo</option><option value="UTC">UTC</option><option value="Europe/London">Europe/London</option><option value="America/New_York">America/New_York</option></select></label><label>并发策略<select v-model="scheduleForm.concurrencyPolicy"><option value="forbid">禁止并发（默认）</option><option value="allow">允许并发</option><option value="replace">替换运行中的任务</option></select></label><label>错过执行<select v-model="scheduleForm.missedPolicy"><option value="skip">跳过并等待下一次</option><option value="run">恢复后补跑一次</option></select></label></div><div class="schedule-preview"><button type="button" :disabled="schedulePreviewing" @click="previewScheduleTimes"><CalendarClock/>{{schedulePreviewing?'计算中':'计算未来 5 次'}}</button><div v-if="scheduleNextRuns.length"><span v-for="run in scheduleNextRuns" :key="run">{{run}}</span></div><em v-if="schedulePreviewError">{{schedulePreviewError}}</em></div><label>执行超时（秒）<input v-model.number="scheduleForm.timeoutSeconds" type="number" min="10" max="86400"></label><label>SSH 凭据<select v-model="scheduleForm.credentialId"><option value="">使用服务端默认密钥</option><option v-for="item in sshCredentials" :key="item.id" :value="item.id">{{item.name}} · {{item.username||'默认用户'}}</option></select></label><label>运行时变量（每行 KEY=值，覆盖 Playbook 默认值）<textarea v-model="scheduleVariablesText" rows="3" placeholder="message=maintenance"></textarea></label><label>执行参数（每行 KEY=值，传给 Runner/模板）<textarea v-model="scheduleParametersText" rows="3" placeholder="env=qa"></textarea></label><label class="schedule-enabled"><input v-model="scheduleForm.enabled" type="checkbox"> 创建后立即启用</label><h3>选择CMDB目标资产 <span>已选 {{scheduleForm.targets.length}} 台</span></h3><div class="target-list"><label v-for="asset in onlineAssets" :key="asset.id"><input v-model="scheduleForm.targets" type="checkbox" :value="asset.id"><div><strong>{{asset.name}}</strong><span>{{asset.ip||asset.id}} · {{asset.environment}} · {{asset.projectGroup}}</span></div><b>{{asset.status}}</b></label></div><footer><button type="button" @click="showSchedule=false">取消</button><button :disabled="scheduleSaving"><CalendarPlus/>{{scheduleSaving?'保存中':'保存计划'}}</button></footer></form></div>
  <div v-if="showPlaybook" class="job-modal" @click.self="showPlaybook=false"><form class="playbook-dialog" @submit.prevent="submitPlaybook"><header><div><small>PLAYBOOK EDITOR</small><h2>{{editingPlaybook?'编辑 Playbook':'新建 Playbook'}}</h2></div><button type="button" @click="showPlaybook=false"><X/></button></header><label>名称<input v-model="playbookForm.name" required maxlength="80"></label><label>描述<textarea v-model="playbookForm.description" rows="2" maxlength="500"></textarea></label><label>剧本内容<textarea v-model="playbookForm.content" rows="8" required placeholder="echo {{message}}" class="code-input"></textarea></label><label>常量（每行 KEY=值，运行时不可覆盖）<textarea v-model="constantsText" rows="4" placeholder="region=shanghai"></textarea></label><label>变量（每行 KEY=默认值，运行时可以覆盖）<textarea v-model="variablesText" rows="4" placeholder="message=hello"></textarea></label><label class="schedule-enabled"><input v-model="playbookForm.enabled" type="checkbox"> 启用 Playbook</label><footer><button type="button" @click="showPlaybook=false">取消</button><button :disabled="playbookSaving">{{playbookSaving?'保存中':'保存 Playbook'}}</button></footer></form></div>
</section></template>
